 public override IMessage Invoke(IMessage message){var call=(IMethodCallMessage)message;var name=call.MethodName.Substring(4);if(ThrowGetters.Contains(name))return new ReturnMessage(new InvalidOperationException("synthetic getter error"),call);Values.TryGetValue(name,out var value);if(value==null){var type=((System.Reflection.MethodInfo)call.MethodBase).ReturnType;value=type.IsValueType?Activator.CreateInstance(type):null;}return new ReturnMessage(value,null,0,call.LogicalCallContext,call);}
